"""`.Eye Textures R`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Eye Textures R'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Eye premade', 'NodeSocketColor')
    t.socket('OUTPUT', 'Eye premade (alpha)', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Eye premade (dark)', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Eye Highlight up', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Eye Highlight down', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('OUTPUT', 'Eye gradient', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Eye pupil', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Star', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Star alpha', 'NodeSocketFloat')
    t.socket('OUTPUT', 'Heart', 'NodeSocketColor', default_value=(0.0, 0.0, 0.0, 0.0))
    t.socket('OUTPUT', 'Heart alpha', 'NodeSocketFloat')
    t.socket('OUTPUT', 'Toon shading', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeFrame', 'Frame.010', props={
        'location': (-945.0, 146.0),
        'width': 721.71716,
        'height': 428.0,
        'label': 'Textures from the texture folder',
        'hide': True,
    })
    t.node('NodeFrame', 'Node', props={
        'location': (-1113.0, -448.0),
        'width': 555.8114,
        'label': 'Permalight mask (R = light, B = dark, dark takes priority)',
        'use_custom_color': True,
        'color': (0.47511104, 0.45669952, 0.33585504),
    })
    t.node('ShaderNodeTexImage', 'perma', parent='Node', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (29.721558, -44.55255),
        'width': 495.81143,
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (-84.045906, 86.13078),
        'width': 136.73825,
    })
    t.node('ShaderNodeTexImage', '_ST_CT.png', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (380.83374, -45.03424),
        'width': 296.78082,
        'label': 'premade eye light',
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', '_ST_DT.png', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (379.31897, -89.6416),
        'width': 300.3613,
        'label': 'premade eye dark',
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', '_ot1.png', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (381.39362, -136.12631),
        'width': 299.83942,
        'label': 'highlight up',
        'hide': True,
        'extension': 'CLIP',
        'image_user': {
            'frame_duration': 1,
            'frame_offset': 6,
        },
    })
    t.node('ShaderNodeTexImage', '_ot2.png', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (381.43195, -184.30725),
        'width': 298.03036,
        'label': 'highlight down',
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', 'Node.001', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (383.28638, -229.97668),
        'width': 284.39172,
        'label': 'eye gradient',
        'hide': True,
        'extension': 'EXTEND',
    })
    t.node('ShaderNodeTexImage', 'Node.002', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (386.71228, -275.38397),
        'width': 286.18967,
        'label': 'pupil',
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeTexImage', '_cf_t_expression_01_EXPR.png', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (377.48932, -321.72632),
        'width': 305.64307,
        'label': 'star overlay',
        'hide': True,
        'show_texture': True,
        'extension': 'CLIP',
        'image_user': {
            'frame_duration': 1,
            'frame_offset': 6,
        },
    })
    t.node('ShaderNodeTexImage', '_cf_t_expression_00_EXPR.png', parent='Frame.010', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (373.62378, -372.95032),
        'width': 317.71716,
        'label': 'heart overlay',
        'hide': True,
        'extension': 'CLIP',
    })
    t.node('ShaderNodeGroup', 'Eyepos', parent='Frame.010', props={
        'node_tree': lib.group('.Eye Textures positioning'),
        'location': (29.847656, -140.01389),
        'width': 266.73346,
    })
    t.node('ShaderNodeGroup', 'shade', inputs={'Use Normals?': 0.0}, props={
        'node_tree': lib.group('.Toon shading'),
        'location': (-464.88565, -285.82895),
        'width': 247.78687,
    })

    t.link('Node.001', 'Color', 'Group Output', 'Eye gradient')
    t.link('Node.002', 'Color', 'Group Output', 'Eye pupil')
    t.link('_ST_CT.png', 'Alpha', 'Group Output', 'Eye premade (alpha)')
    t.link('_ot1.png', 'Alpha', 'Group Output', 'Eye Highlight up')
    t.link('_ot2.png', 'Alpha', 'Group Output', 'Eye Highlight down')
    t.link('_ST_CT.png', 'Color', 'Group Output', 'Eye premade')
    t.link('_cf_t_expression_01_EXPR.png', 'Color', 'Group Output', 'Star')
    t.link('_cf_t_expression_01_EXPR.png', 'Alpha', 'Group Output', 'Star alpha')
    t.link('_cf_t_expression_00_EXPR.png', 'Color', 'Group Output', 'Heart')
    t.link('_cf_t_expression_00_EXPR.png', 'Alpha', 'Group Output', 'Heart alpha')
    t.link('_ST_DT.png', 'Color', 'Group Output', 'Eye premade (dark)')
    t.link('Eyepos', 'Eye Scaling', 'Node.002', 'Vector')
    t.link('Eyepos', 'Eye Scaling', '_ST_CT.png', 'Vector')
    t.link('Eyepos', 'Eye Scaling', '_ST_DT.png', 'Vector')
    t.link('Eyepos', 'highlight up position', '_ot1.png', 'Vector')
    t.link('Eyepos', 'highlight down position', '_ot2.png', 'Vector')
    t.link('perma', 'Color', 'shade', 'Permalight mask')
    t.link('shade', 'Toon shading', 'Group Output', 'Toon shading')
    t.link('Eyepos', 'gradient positioning', 'Node.001', 'Vector')
    return t
